import os

import pytest

from zeta.protocol.types import ToolCall
from zeta.skills import SkillCatalog
from zeta.tools import ToolRegistry


@pytest.mark.asyncio
async def test_file_tools_borrow_target_descriptor(tmp_path, monkeypatch):
    original_fdopen = os.fdopen
    observed = []

    def tracked_fdopen(fd, mode="r", *args, **kwargs):
        if mode in {"wb", "rb", "r+b"}:
            assert kwargs.get("closefd") is False
            observed.append(mode)
        return original_fdopen(fd, mode, *args, **kwargs)

    monkeypatch.setattr(os, "fdopen", tracked_fdopen)
    registry = ToolRegistry(tmp_path, skill_catalog=SkillCatalog.empty())
    try:
        calls = (
            ToolCall("write", "write", {"path": "note.txt", "content": "before"}),
            ToolCall("read", "read", {"path": "note.txt"}),
            ToolCall("edit", "edit", {
                "path": "note.txt", "old_string": "before", "new_string": "after"
            }),
        )
        for call in calls:
            result = await registry.execute(call)
            assert not result["isError"], result
        assert observed == ["wb", "rb", "r+b"]
        assert (tmp_path / "note.txt").read_text() == "after"
    finally:
        await registry.close()

@pytest.mark.asyncio
async def test_fdopen_failure_closes_target_once(tmp_path, monkeypatch):
    real_fdopen = os.fdopen
    real_close = os.close
    target_fd = None
    closed = []

    def failing_fdopen(fd, mode="r", *args, **kwargs):
        nonlocal target_fd
        if mode == "wb":
            target_fd = fd
            raise OSError("simulated fdopen failure")
        return real_fdopen(fd, mode, *args, **kwargs)

    def tracked_close(fd):
        if fd == target_fd:
            closed.append(fd)
        return real_close(fd)

    monkeypatch.setattr(os, "fdopen", failing_fdopen)
    monkeypatch.setattr(os, "close", tracked_close)
    registry = ToolRegistry(tmp_path, skill_catalog=SkillCatalog.empty())
    try:
        result = await registry.execute(
            ToolCall("write", "write", {"path": "failure.txt", "content": "data"})
        )
        assert result["isError"] is True
        assert target_fd is not None
        assert closed == [target_fd]
    finally:
        await registry.close()

@pytest.mark.asyncio
async def test_missing_nonowning_fdopen_fails_closed(tmp_path, monkeypatch):
    real_fdopen = os.fdopen
    owning_calls = []

    def owning_only_fdopen(fd, mode="r"):
        owning_calls.append((fd, mode))
        return real_fdopen(fd, mode)

    monkeypatch.setattr(os, "fdopen", owning_only_fdopen)
    registry = ToolRegistry(tmp_path, skill_catalog=SkillCatalog.empty())
    try:
        result = await registry.execute(
            ToolCall("write", "write", {"path": "unsupported.txt", "content": "data"})
        )
        assert result["isError"] is True
        assert owning_calls == []
    finally:
        await registry.close()
